module dff_async_reset(
    input  wire clk,
    input  wire rst,
    input  wire d,
    output reg  q
);
    always @(posedge clk or posedge rst) begin
        if (rst) q <= 1'b0;
        else     q <= d;
    end
endmodule

module reg8(
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [7:0] d,
    output reg  [7:0] q
);
    always @(posedge clk) begin
        if (rst)      q <= 8'd0;
        else if (en)  q <= d;
    end
endmodule

module counter8(
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    output reg  [7:0] q
);
    always @(posedge clk) begin
        if (rst)      q <= 8'd0;
        else if (en)  q <= q + 1'b1;
    end
endmodule

module shift_reg8(
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       serial_in,
    output reg  [7:0] q
);
    always @(posedge clk) begin
        if (rst)      q <= 8'd0;
        else if (en)  q <= {q[6:0], serial_in};
    end
endmodule

module dec2to4(
    input  wire [1:0] a,
    input  wire       en,
    output wire [3:0] y
);
    assign y = en ? (4'b0001 << a) : 4'b0000;
endmodule

module clk_div_pow2 #(
    parameter N = 1
)(
    input  wire clk,
    input  wire rst,
    output wire clk_out
);
    reg [N-1:0] cnt;
    always @(posedge clk) begin
        if (rst) cnt <= {N{1'b0}};
        else     cnt <= cnt + 1'b1;
    end
    assign clk_out = cnt[N-1];
endmodule

module edge_detect(
    input  wire clk,
    input  wire rst,
    input  wire d,
    output wire rising
);
    reg d1;
    always @(posedge clk) begin
        if (rst) d1 <= 1'b0;
        else     d1 <= d;
    end
    assign rising = d & ~d1;
endmodule

module sync_2ff(
    input  wire clk,
    input  wire d_async,
    output reg  q
);
    reg q1;
    always @(posedge clk) begin
        q1 <= d_async;
        q  <= q1;
    end
endmodule

module cmp8(
